"""Scenario validation and normalization.

A decoded JSON object goes in; either a :class:`ScenarioError` describes the
first violated constraint or a normalized config dict comes out. All
structural and cross-reference checks run here, before any event is
scheduled, so the simulation core only ever sees a legal scenario.
"""

from __future__ import annotations

_TOP_LEVEL_FIELDS = {
    "nodes",
    "duration",
    "electionTimeouts",
    "heartbeatInterval",
    "messageDelay",
    "faults",
    "clientCommands",
    "nodeEvents",
    "snapshotThreshold",
    "initialMembers",
    "membershipChanges",
    "messageFaults",
    "readQueries",
    "livenessChecks",
    "preVote",
}
_REQUIRED_FIELDS = _TOP_LEVEL_FIELDS - {
    "faults",
    "clientCommands",
    "nodeEvents",
    "snapshotThreshold",
    "initialMembers",
    "membershipChanges",
    "messageFaults",
    "readQueries",
    "livenessChecks",
    "preVote",
}
_FAULT_FIELDS = {"time", "action", "groups"}
_MESSAGE_FAULT_FIELDS = {"from", "to", "message", "occurrence", "action", "delay"}
_MESSAGE_FAULT_REQUIRED = {"from", "to", "message", "occurrence", "action"}
_MESSAGE_KINDS = (
    "requestVote",
    "voteReply",
    "preVote",
    "preVoteReply",
    "heartbeat",
    "appendEntries",
    "appendReply",
    "installSnapshot",
    "installSnapshotReply",
    "readProbe",
    "readReply",
)
# Pre-vote traffic exists only while the optional phase is enabled; a rule
# referencing either kind in a preVote-less scenario makes the scenario illegal.
_PRE_VOTE_MESSAGE_KINDS = ("preVote", "preVoteReply")
_CLIENT_COMMAND_FIELDS = {"time", "node", "id", "command"}
_NODE_EVENT_FIELDS = {"time", "node", "action"}
_MEMBERSHIP_CHANGE_FIELDS = {"time", "node", "id", "action", "member"}
_READ_QUERY_FIELDS = {"time", "node", "id"}
_LIVENESS_CHECK_FIELDS = {"id", "type", "startTime", "deadline", "target"}
_LIVENESS_TYPES = (
    "leaderElected",
    "clientCommitted",
    "readCompleted",
    "membershipCommitted",
)
_LIVENESS_TARGET_TYPES = {
    "clientCommitted": "clientCommands",
    "readCompleted": "readQueries",
    "membershipCommitted": "membershipChanges",
}

class ScenarioError(Exception):
    """The scenario input is invalid."""


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _require_int(value: object, name: str, minimum: int) -> int:
    if not _is_int(value):
        raise ScenarioError(f"{name} must be an integer")
    if value < minimum:
        if minimum > 0:
            raise ScenarioError(f"{name} must be a positive integer")
        raise ScenarioError(f"{name} must be a non-negative integer")
    return value


def parse_scenario(raw: object) -> dict:
    """Validate the decoded JSON scenario and return a normalized config."""
    if not isinstance(raw, dict):
        raise ScenarioError("scenario must be a JSON object")
    unknown = sorted(set(raw) - _TOP_LEVEL_FIELDS)
    if unknown:
        raise ScenarioError(f"unknown field(s): {', '.join(unknown)}")
    missing = sorted(_REQUIRED_FIELDS - set(raw))
    if missing:
        raise ScenarioError(f"missing field(s): {', '.join(missing)}")

    nodes = raw["nodes"]
    if not isinstance(nodes, list) or len(nodes) < 3:
        raise ScenarioError("nodes must be a list of at least three names")
    for name in nodes:
        if not isinstance(name, str) or not name:
            raise ScenarioError("node names must be non-empty strings")
    if len(set(nodes)) != len(nodes):
        raise ScenarioError("node names must be unique")

    duration = _require_int(raw["duration"], "duration", 0)
    heartbeat = _require_int(raw["heartbeatInterval"], "heartbeatInterval", 1)
    delay = _require_int(raw["messageDelay"], "messageDelay", 0)

    timeouts_raw = raw["electionTimeouts"]
    if _is_int(timeouts_raw):
        _require_int(timeouts_raw, "electionTimeouts", 1)
        timeouts = {name: timeouts_raw for name in nodes}
    elif isinstance(timeouts_raw, dict):
        unknown_nodes = sorted(set(timeouts_raw) - set(nodes))
        if unknown_nodes:
            raise ScenarioError(
                f"electionTimeouts references unknown node(s): {', '.join(unknown_nodes)}"
            )
        missing_nodes = sorted(set(nodes) - set(timeouts_raw))
        if missing_nodes:
            raise ScenarioError(
                f"electionTimeouts is missing node(s): {', '.join(missing_nodes)}"
            )
        timeouts = {}
        for name in nodes:
            timeouts[name] = _require_int(timeouts_raw[name], f"electionTimeouts.{name}", 1)
    else:
        raise ScenarioError("electionTimeouts must be a positive integer or an object mapping node names to positive integers")

    # The optional pre-vote phase is opt-in: omitted or false keeps every
    # legacy scenario's behavior (and output) byte for byte, and the
    # pre-vote message kinds become illegal.
    pre_vote = raw.get("preVote", False)
    if not isinstance(pre_vote, bool):
        raise ScenarioError("preVote must be a boolean")

    faults = raw.get("faults", [])
    if not isinstance(faults, list):
        raise ScenarioError("faults must be a list")
    normalized_faults = []
    node_set = set(nodes)
    for index, fault in enumerate(faults):
        label = f"faults[{index}]"
        if not isinstance(fault, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(fault) - _FAULT_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        if "time" not in fault or "action" not in fault:
            raise ScenarioError(f"{label} must have time and action")
        time = _require_int(fault["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        action = fault["action"]
        if action == "partition":
            if "groups" not in fault:
                raise ScenarioError(f"{label} partition requires groups")
            groups = fault["groups"]
            if not isinstance(groups, list) or len(groups) != 2:
                raise ScenarioError(f"{label}.groups must contain exactly two groups")
            seen: set[str] = set()
            normalized_groups = []
            for group in groups:
                if not isinstance(group, list) or not group:
                    raise ScenarioError(f"{label}.groups entries must be non-empty lists")
                for member in group:
                    if member not in node_set:
                        raise ScenarioError(f"{label}.groups references unknown node: {member!r}")
                    if member in seen:
                        raise ScenarioError(f"{label}.groups must not overlap")
                    seen.add(member)
                normalized_groups.append(list(group))
            if seen != node_set:
                raise ScenarioError(f"{label}.groups must cover every node")
            normalized_faults.append({"time": time, "action": "partition", "groups": normalized_groups})
        elif action == "heal":
            if "groups" in fault:
                raise ScenarioError(f"{label} heal must not have groups")
            normalized_faults.append({"time": time, "action": "heal"})
        else:
            raise ScenarioError(f"{label}.action must be partition or heal")

    message_faults = raw.get("messageFaults", [])
    if not isinstance(message_faults, list):
        raise ScenarioError("messageFaults must be a list")
    normalized_message_faults = []
    seen_selectors: dict[tuple, int] = {}
    for index, message_fault in enumerate(message_faults):
        label = f"messageFaults[{index}]"
        if not isinstance(message_fault, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(message_fault) - _MESSAGE_FAULT_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_MESSAGE_FAULT_REQUIRED - set(message_fault))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        src = message_fault["from"]
        if not isinstance(src, str) or not src:
            raise ScenarioError(f"{label}.from must be a non-empty string")
        if src not in node_set:
            raise ScenarioError(f"{label}.from references unknown node: {src!r}")
        dst = message_fault["to"]
        if not isinstance(dst, str) or not dst:
            raise ScenarioError(f"{label}.to must be a non-empty string")
        if dst not in node_set:
            raise ScenarioError(f"{label}.to references unknown node: {dst!r}")
        if src == dst:
            raise ScenarioError(f"{label}.from and {label}.to must be different nodes")
        kind = message_fault["message"]
        if kind in _PRE_VOTE_MESSAGE_KINDS and not pre_vote:
            raise ScenarioError(
                f"{label}.message {kind!r} is only valid when preVote is enabled"
            )
        if kind not in _MESSAGE_KINDS:
            raise ScenarioError(
                f"{label}.message must be one of: {', '.join(_MESSAGE_KINDS)}"
            )
        occurrence = _require_int(message_fault["occurrence"], f"{label}.occurrence", 1)
        action = message_fault["action"]
        if action not in ("drop", "delay"):
            raise ScenarioError(f"{label}.action must be drop or delay")
        extra_delay = None
        if action == "drop":
            if "delay" in message_fault:
                raise ScenarioError(f"{label} drop must not have delay")
        else:
            if "delay" not in message_fault:
                raise ScenarioError(f"{label} delay requires delay")
            extra_delay = _require_int(message_fault["delay"], f"{label}.delay", 0)
        selector = (src, dst, kind, occurrence)
        if selector in seen_selectors:
            raise ScenarioError(
                f"{label} duplicates the selector of messageFaults[{seen_selectors[selector]}]"
            )
        seen_selectors[selector] = index
        normalized = {
            "index": index,
            "from": src,
            "to": dst,
            "message": kind,
            "occurrence": occurrence,
            "action": action,
        }
        if extra_delay is not None:
            normalized["delay"] = extra_delay
        normalized_message_faults.append(normalized)

    commands = raw.get("clientCommands", [])
    if not isinstance(commands, list):
        raise ScenarioError("clientCommands must be a list")
    normalized_commands = []
    seen_ids: set[str] = set()
    for index, command in enumerate(commands):
        label = f"clientCommands[{index}]"
        if not isinstance(command, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(command) - _CLIENT_COMMAND_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_CLIENT_COMMAND_FIELDS - set(command))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        time = _require_int(command["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        node = command["node"]
        if not isinstance(node, str) or not node:
            raise ScenarioError(f"{label}.node must be a non-empty string")
        if node not in node_set:
            raise ScenarioError(f"{label}.node references unknown node: {node!r}")
        command_id = command["id"]
        if not isinstance(command_id, str) or not command_id:
            raise ScenarioError(f"{label}.id must be a non-empty string")
        if command_id in seen_ids:
            raise ScenarioError(f"{label}.id duplicates a previous id: {command_id!r}")
        seen_ids.add(command_id)
        # "command" may be any JSON value; decoding already guaranteed validity.
        normalized_commands.append(
            {"time": time, "node": node, "id": command_id, "command": command["command"]}
        )

    node_events_provided = "nodeEvents" in raw
    node_events = raw.get("nodeEvents", [])
    if not isinstance(node_events, list):
        raise ScenarioError("nodeEvents must be a list")
    normalized_node_events = []
    last_action: dict[str, str] = {}
    for index, event in enumerate(node_events):
        label = f"nodeEvents[{index}]"
        if not isinstance(event, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(event) - _NODE_EVENT_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_NODE_EVENT_FIELDS - set(event))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        time = _require_int(event["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        node = event["node"]
        if not isinstance(node, str) or not node:
            raise ScenarioError(f"{label}.node must be a non-empty string")
        if node not in node_set:
            raise ScenarioError(f"{label}.node references unknown node: {node!r}")
        action = event["action"]
        if action not in ("crash", "restart"):
            raise ScenarioError(f"{label}.action must be crash or restart")
        previous = last_action.get(node)
        if previous is None and action != "crash":
            raise ScenarioError(f"{label}: first event for node {node!r} must be crash")
        if previous == action:
            raise ScenarioError(
                f"{label}: events for node {node!r} must alternate crash and restart"
            )
        last_action[node] = action
        normalized_node_events.append({"time": time, "node": node, "action": action})

    snapshot_threshold = None
    if "snapshotThreshold" in raw:
        snapshot_threshold = _require_int(
            raw["snapshotThreshold"], "snapshotThreshold", 1
        )

    has_initial_members = "initialMembers" in raw
    has_membership_changes = "membershipChanges" in raw
    if has_initial_members != has_membership_changes:
        raise ScenarioError(
            "initialMembers and membershipChanges must be provided together"
        )

    initial_members: list[str] | None = None
    membership_enabled = has_initial_members
    seen_change_ids: set[str] = set()
    if has_initial_members:
        raw_initial = raw["initialMembers"]
        if not isinstance(raw_initial, list) or len(raw_initial) < 3:
            raise ScenarioError(
                "initialMembers must be a list of at least three node names"
            )
        for name in raw_initial:
            if not isinstance(name, str) or not name:
                raise ScenarioError("initialMembers entries must be non-empty strings")
            if name not in node_set:
                raise ScenarioError(
                    f"initialMembers references unknown node: {name!r}"
                )
        if len(set(raw_initial)) != len(raw_initial):
            raise ScenarioError("initialMembers entries must be unique")
        initial_members = list(raw_initial)

        raw_changes = raw["membershipChanges"]
        if not isinstance(raw_changes, list):
            raise ScenarioError("membershipChanges must be a list")
        normalized_changes = []
        for index, change in enumerate(raw_changes):
            label = f"membershipChanges[{index}]"
            if not isinstance(change, dict):
                raise ScenarioError(f"{label} must be an object")
            unknown = sorted(set(change) - _MEMBERSHIP_CHANGE_FIELDS)
            if unknown:
                raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
            missing = sorted(_MEMBERSHIP_CHANGE_FIELDS - set(change))
            if missing:
                raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
            time = _require_int(change["time"], f"{label}.time", 0)
            if time > duration:
                raise ScenarioError(f"{label}.time is beyond the simulation duration")
            node = change["node"]
            if not isinstance(node, str) or not node:
                raise ScenarioError(f"{label}.node must be a non-empty string")
            if node not in node_set:
                raise ScenarioError(f"{label}.node references unknown node: {node!r}")
            change_id = change["id"]
            if not isinstance(change_id, str) or not change_id:
                raise ScenarioError(f"{label}.id must be a non-empty string")
            if change_id in seen_change_ids:
                raise ScenarioError(
                    f"{label}.id duplicates a previous id: {change_id!r}"
                )
            seen_change_ids.add(change_id)
            if change_id in seen_ids:
                raise ScenarioError(
                    f"{label}.id duplicates a clientCommands id: {change_id!r}"
                )
            action = change["action"]
            if action not in ("add", "remove"):
                raise ScenarioError(f"{label}.action must be add or remove")
            member = change["member"]
            if not isinstance(member, str) or not member:
                raise ScenarioError(f"{label}.member must be a non-empty string")
            if member not in node_set:
                raise ScenarioError(
                    f"{label}.member references unknown node: {member!r}"
                )
            normalized_changes.append(
                {
                    "time": time,
                    "node": node,
                    "id": change_id,
                    "action": action,
                    "member": member,
                }
            )

    read_queries_provided = "readQueries" in raw
    read_queries = raw.get("readQueries", [])
    if not isinstance(read_queries, list):
        raise ScenarioError("readQueries must be a list")
    normalized_read_queries = []
    seen_read_ids: set[str] = set()
    for index, query in enumerate(read_queries):
        label = f"readQueries[{index}]"
        if not isinstance(query, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(query) - _READ_QUERY_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_READ_QUERY_FIELDS - set(query))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        time = _require_int(query["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        node = query["node"]
        if not isinstance(node, str) or not node:
            raise ScenarioError(f"{label}.node must be a non-empty string")
        if node not in node_set:
            raise ScenarioError(f"{label}.node references unknown node: {node!r}")
        query_id = query["id"]
        if not isinstance(query_id, str) or not query_id:
            raise ScenarioError(f"{label}.id must be a non-empty string")
        if query_id in seen_read_ids:
            raise ScenarioError(f"{label}.id duplicates a previous id: {query_id!r}")
        if query_id in seen_ids:
            raise ScenarioError(
                f"{label}.id duplicates a clientCommands id: {query_id!r}"
            )
        if query_id in seen_change_ids:
            raise ScenarioError(
                f"{label}.id duplicates a membershipChanges id: {query_id!r}"
            )
        seen_read_ids.add(query_id)
        normalized_read_queries.append({"time": time, "node": node, "id": query_id})

    liveness_provided = "livenessChecks" in raw
    liveness_checks = raw.get("livenessChecks", [])
    if not isinstance(liveness_checks, list):
        raise ScenarioError("livenessChecks must be a list")
    normalized_liveness_checks = []
    seen_check_ids: set[str] = set()
    for index, check in enumerate(liveness_checks):
        label = f"livenessChecks[{index}]"
        if not isinstance(check, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(check) - _LIVENESS_CHECK_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_LIVENESS_CHECK_FIELDS - {"target"} - set(check))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        check_id = check["id"]
        if not isinstance(check_id, str) or not check_id:
            raise ScenarioError(f"{label}.id must be a non-empty string")
        if check_id in seen_check_ids:
            raise ScenarioError(f"{label}.id duplicates a previous id: {check_id!r}")
        seen_check_ids.add(check_id)
        check_type = check["type"]
        if check_type not in _LIVENESS_TYPES:
            raise ScenarioError(
                f"{label}.type must be one of: {', '.join(_LIVENESS_TYPES)}"
            )
        start_time = _require_int(check["startTime"], f"{label}.startTime", 0)
        if start_time > duration:
            raise ScenarioError(f"{label}.startTime is beyond the simulation duration")
        deadline = _require_int(check["deadline"], f"{label}.deadline", 0)
        if deadline > duration:
            raise ScenarioError(f"{label}.deadline is beyond the simulation duration")
        if start_time > deadline:
            raise ScenarioError(f"{label}.startTime must not be greater than deadline")
        if check_type == "leaderElected":
            if "target" in check:
                raise ScenarioError(f"{label} leaderElected must not have a target")
            target = None
        else:
            if "target" not in check:
                raise ScenarioError(f"{label} {check_type} requires a target")
            target = check["target"]
            if not isinstance(target, str) or not target:
                raise ScenarioError(f"{label}.target must be a non-empty string")
            container = _LIVENESS_TARGET_TYPES[check_type]
            if container == "clientCommands" and target not in seen_ids:
                raise ScenarioError(
                    f"{label}.target references an unknown clientCommands id: {target!r}"
                )
            if container == "readQueries" and target not in seen_read_ids:
                raise ScenarioError(
                    f"{label}.target references an unknown readQueries id: {target!r}"
                )
            if container == "membershipChanges" and target not in seen_change_ids:
                raise ScenarioError(
                    f"{label}.target references an unknown membershipChanges id: {target!r}"
                )
        normalized_liveness_checks.append(
            {
                "id": check_id,
                "type": check_type,
                "startTime": start_time,
                "deadline": deadline,
                "target": target,
            }
        )

    return {
        "nodes": list(nodes),
        "duration": duration,
        "electionTimeouts": timeouts,
        "heartbeatInterval": heartbeat,
        "messageDelay": delay,
        "faults": normalized_faults,
        "messageFaults": normalized_message_faults,
        "clientCommands": normalized_commands,
        "nodeEvents": normalized_node_events,
        "nodeEventsProvided": node_events_provided,
        "snapshotThreshold": snapshot_threshold,
        "membershipEnabled": membership_enabled,
        "initialMembers": initial_members,
        "membershipChanges": normalized_changes if has_initial_members else None,
        "readQueries": normalized_read_queries,
        "readQueriesProvided": read_queries_provided,
        "livenessChecks": normalized_liveness_checks,
        "livenessChecksProvided": liveness_provided,
        "preVote": pre_vote,
    }

"""Timeline recording and message dispatch: the shared kernel every
protocol domain runs on.

``_Kernel`` owns the two things no domain may reimplement: appending to the
single simulation timeline (``_record`` / ``_record_state_change``) and
routing a delivered message to its domain handler (``_deliver``). All
state changes, message sends, zero-delay cascades, commit applications and
liveness results flow through ``_record`` into the one timeline, in the
established deterministic order.

Provides (to every domain mixin):
    _record, _record_state_change, _deliver

Requires (from the composing simulator):
    ``timeline``, ``now``, ``state``, ``network`` and the per-domain
    message handlers mixed in alongside this class.
"""

from __future__ import annotations


class _Kernel:
    # -- timeline helpers -------------------------------------------------

    def _record(self, entry: dict) -> None:
        self.timeline.append({"seq": len(self.timeline) + 1, "time": self.now, **entry})

    def _record_state_change(self, name: str, reason: str) -> None:
        st = self.state[name]
        self._record({"type": "stateChange", "node": name, "term": st.term, "role": st.role, "reason": reason})

    # -- message dispatch -----------------------------------------------------

    def _deliver(self, msg: dict) -> None:
        if not self.network.deliver(msg, self.state[msg["dst"]].online):
            return
        kind = msg["kind"]
        if kind == "requestVote":
            self._handle_request_vote(msg)
        elif kind == "voteReply":
            self._handle_vote_reply(msg)
        elif kind == "preVote":
            self._handle_pre_vote(msg)
        elif kind == "preVoteReply":
            self._handle_pre_vote_reply(msg)
        elif kind == "heartbeat":
            self._handle_heartbeat(msg)
        elif kind == "appendEntries":
            self._handle_append_entries(msg)
        elif kind == "installSnapshot":
            self._handle_install_snapshot(msg)
        elif kind == "installSnapshotReply":
            self._handle_snapshot_reply(msg)
        elif kind == "readProbe":
            self._handle_read_probe(msg)
        elif kind == "readReply":
            self._handle_read_reply(msg)
        else:
            self._handle_append_reply(msg)

"""Final report generation.

Everything here is read-only over the finished simulation: the timeline, the
final node states and the bookkeeping accumulated during the run are
projected into the client/membership/read summaries and the election-safety,
log-matching, state-machine-safety, linearizability and liveness reports.
Nothing in this module mutates simulator state.
"""

from __future__ import annotations

import json

from .node import CONFIG_JOINT, KIND_CONFIG, _Node


def _log_matching_violations(sim) -> list[dict]:
    """Same index and term, but different content (id/command for client
    commands, or the configuration payload) across nodes, including
    indices folded into snapshots or occupied by configuration entries."""
    violations = []
    max_len = max((st.last_log_index() for st in sim.state.values()), default=0)
    for index in range(1, max_len + 1):
        by_term: dict[int, dict[tuple, dict]] = {}
        for name in sim.node_names:
            st = sim.state[name]
            entry = sim._entry_view(st, index)
            if entry is None:
                continue
            if entry.get("kind") == KIND_CONFIG:
                marker = json.dumps(
                    [
                        entry["id"],
                        KIND_CONFIG,
                        entry["entryType"],
                        entry.get("config"),
                        entry.get("action"),
                        entry.get("member"),
                    ],
                    ensure_ascii=False,
                    sort_keys=True,
                )
                bucket_view = {
                    "id": entry["id"],
                    "kind": KIND_CONFIG,
                    "entryType": entry["entryType"],
                    "config": entry.get("config"),
                    "nodes": [],
                }
            else:
                marker = json.dumps([entry["id"], entry["command"]], ensure_ascii=False, sort_keys=True)
                bucket_view = {"id": entry["id"], "command": entry["command"], "nodes": []}
            bucket = by_term.setdefault(entry["term"], {}).setdefault(marker, bucket_view)
            bucket["nodes"].append(name)
        for term, variants in sorted(by_term.items()):
            if len(variants) > 1:
                violations.append(
                    {
                        "index": index,
                        "term": term,
                        "variants": [bucket for _marker, bucket in sorted(variants.items())],
                    }
                )
    return violations

def _state_machine_safety_violations(sim) -> list[dict]:
    """Different nodes applied different entries at the same index.
    Configuration entries participate in index alignment alongside client
    commands, and applied histories recovered from snapshots are covered."""
    violations = []
    max_applied = max((st.last_applied for st in sim.state.values()), default=0)
    for index in range(1, max_applied + 1):
        variants: dict[str, dict] = {}
        for name in sim.node_names:
            st = sim.state[name]
            if index > st.last_applied:
                continue
            entry = st.applied[index - 1]
            if entry.get("kind") == KIND_CONFIG:
                marker = json.dumps(
                    [
                        entry["term"],
                        entry["id"],
                        KIND_CONFIG,
                        entry["entryType"],
                        entry.get("config"),
                    ],
                    ensure_ascii=False,
                    sort_keys=True,
                )
                bucket = variants.setdefault(
                    marker,
                    {
                        "term": entry["term"],
                        "id": entry["id"],
                        "kind": KIND_CONFIG,
                        "entryType": entry["entryType"],
                        "config": entry.get("config"),
                        "nodes": [],
                    },
                )
            else:
                marker = json.dumps([entry["term"], entry["id"], entry["command"]], ensure_ascii=False, sort_keys=True)
                bucket = variants.setdefault(
                    marker, {"term": entry["term"], "id": entry["id"], "command": entry["command"], "nodes": []}
                )
            bucket["nodes"].append(name)
        if len(variants) > 1:
            violations.append(
                {"index": index, "variants": [bucket for marker, bucket in sorted(variants.items())]}
            )
    return violations

def _clients_report(sim) -> dict:
    grouped: dict[str, list[dict]] = {
        "committed": [],
        "superseded": [],
        "pending": [],
        "rejected": [],
    }

    def find_applied(command_id: str) -> dict | None:
        for name in sim.node_names:
            for entry in sim.state[name].applied:
                if entry["id"] == command_id:
                    return entry
        return None

    def in_any_log(command_id: str) -> dict | None:
        for name in sim.node_names:
            for entry in sim.state[name].log:
                if entry["id"] == command_id:
                    return entry
        return None

    for command in sim.commands:
        command_id = command["id"]
        if command_id in sim.rejected:
            rejected = sim.rejected[command_id]
            grouped["rejected"].append(
                {
                    "id": command_id,
                    "node": command["node"],
                    "reason": rejected["reason"],
                    "knownLeader": rejected["knownLeader"],
                }
            )
            continue
        applied = find_applied(command_id)
        if applied is not None:
            grouped["committed"].append(
                {
                    "id": command_id,
                    "node": command["node"],
                    "index": applied["index"],
                    "term": applied["term"],
                }
            )
            continue
        present = in_any_log(command_id)
        if present is not None:
            grouped["pending"].append(
                {
                    "id": command_id,
                    "node": command["node"],
                    "index": present["index"],
                    "term": present["term"],
                }
            )
        else:
            grouped["superseded"].append({"id": command_id, "node": command["node"]})
    return grouped

def _node_report(sim, name: str, st: _Node) -> dict:
    report = {
        "role": st.role,
        "term": st.term,
        "votedFor": st.voted_for,
        "knownLeader": st.known_leader,
        "log": [dict(entry) for entry in st.log],
        "commitIndex": st.commit_index,
        "lastApplied": st.last_applied,
        "applied": [dict(entry) for entry in st.applied],
    }
    if sim.membership_enabled:
        # Voter/learner according to the node's newest configuration,
        # which governs voting and campaigning even before it commits.
        report["membershipRole"] = (
            "voter" if sim._is_voter(name, st.latest_config(sim.initial_config)) else "learner"
        )
    if sim.snapshot_threshold is not None:
        if st.snapshot_index > 0:
            report["snapshot"] = {
                "lastIncludedIndex": st.snapshot_index,
                "lastIncludedTerm": st.snapshot_term,
            }
        else:
            report["snapshot"] = None
    if sim.node_events_provided:
        report["online"] = st.online
        report["restartCount"] = st.restart_count
    return report

def _membership_report(sim) -> dict:
    # The reference node deterministically has the greatest committed
    # position, then the greatest log length (declared node order breaks
    # ties): committed truth dominates, so a deposed leader's stale
    # uncommitted suffix cannot describe a phase the cluster left.
    ref_name = max(
        sim.node_names,
        key=lambda name: (
            sim.state[name].commit_index,
            sim.state[name].last_log_index(),
            -sim.index[name],
        ),
    )
    ref = sim.state[ref_name]
    committed = ref.committed_config(sim.initial_config)
    latest = ref.latest_config(sim.initial_config)

    if latest.get("type") == CONFIG_JOINT:
        old, new = sim._config_groups(latest)
        current_stable = sorted(old)
        joint = {"id": _latest_joint_id(ref),
                 "old": sorted(old), "new": sorted(new)}
    elif committed.get("type") == CONFIG_JOINT:
        old, new = sim._config_groups(committed)
        current_stable = sorted(old)
        joint = {"id": _latest_joint_id(ref),
                 "old": sorted(old), "new": sorted(new)}
    else:
        _, stable_voters = sim._config_groups(committed)
        current_stable = sorted(stable_voters)
        joint = None

    joint_ids = set()
    for st in sim.state.values():
        for applied in st.applied:
            if applied.get("kind") == KIND_CONFIG and applied["entryType"] == CONFIG_JOINT:
                joint_ids.add(applied["id"])
        for log_entry in st.log:
            if log_entry.get("kind") == KIND_CONFIG and log_entry["entryType"] == CONFIG_JOINT:
                joint_ids.add(log_entry["id"])

    changes = []
    for change in sim.changes:
        change_id = change["id"]
        result = sim.change_results.get(change_id)
        entry = {
            "id": change_id,
            "node": change["node"],
            "action": change["action"],
            "member": change["member"],
        }
        if result is None or result.get("outcome") == "pending":
            entry["outcome"] = "pending"
            if sim.pending_catchup is not None and sim.pending_catchup["id"] == change_id:
                entry["phase"] = "catchingUp"
            elif change_id in joint_ids:
                phase_info = result.get("jointPhase") if result else None
                entry["phase"] = "joint"
                if phase_info is not None:
                    entry["joint"] = {
                        "old": sorted(phase_info["old"]),
                        "new": sorted(phase_info["new"]),
                    }
            else:
                entry["phase"] = "catchingUp"
        elif result.get("outcome") == "rejected":
            entry["outcome"] = "rejected"
            entry["reason"] = result["reason"]
        else:
            entry["outcome"] = "committed"
            entry["index"] = result["index"]
            entry["term"] = result["term"]
        changes.append(entry)

    return {
        "initial": sorted(sim.initial_config["new"]),
        "current": current_stable,
        "joint": joint,
        "changes": changes,
    }

def _latest_config_entry_id(st: _Node, entry_type: str) -> str | None:
    """The id of the newest committed configuration entry of a type,
    looking through the snapshot into the applied history."""
    found = None
    for entry in st.applied:
        if entry.get("kind") == KIND_CONFIG and entry["entryType"] == entry_type:
            found = entry["id"]
    upper = min(st.commit_index, st.last_log_index())
    for i in range(st.snapshot_index + 1, upper + 1):
        entry = st.log[i - 1 - st.snapshot_index]
        if entry.get("kind") == KIND_CONFIG and entry["entryType"] == entry_type:
            found = entry["id"]
    return found

def _latest_joint_id(st: _Node) -> str | None:
    """The id of the newest joint configuration entry the reference node
    holds, including one appended but not yet committed."""
    found = _latest_config_entry_id(st, CONFIG_JOINT)
    for entry in st.log:
        if entry.get("kind") == KIND_CONFIG and entry["entryType"] == CONFIG_JOINT:
            found = entry["id"]
    return found

def _reads_report(sim) -> list[dict]:
    """The final outcome of every read query, in input order. Queries
    still awaiting a majority confirmation when the simulation ends are
    reported as pending."""
    reads = []
    for query in sim.read_queries:
        query_id = query["id"]
        result = sim.read_results.get(query_id)
        if result is None:
            pending = sim.pending_reads[query_id]
            result = {
                "outcome": "pending",
                "term": pending["term"],
                "readIndex": pending["readIndex"],
            }
        reads.append({"id": query_id, "node": query["node"], **result})
    return reads

def _linearizability_violations(sim) -> list[dict]:
    """Per completed read, checked in input order:
    - nonPrefix: the returned state is not the complete client-command
      prefix of the serving leader's applied history up to readIndex
      (configuration entries excluded, compacted commands included);
    - staleRead: the state omits a write that was already committed when
      the query was accepted."""
    violations = []
    for query in sim.read_queries:
        query_id = query["id"]
        result = sim.read_results.get(query_id)
        if result is None or result.get("outcome") != "completed":
            continue
        read_index = result["readIndex"]
        st = sim.state[query["node"]]
        expected = [
            sim._read_state_entry(entry)
            for entry in st.applied[:read_index]
            if entry.get("kind") != KIND_CONFIG
        ]
        if result["state"] != expected:
            violations.append(
                {"type": "nonPrefix", "id": query_id, "readIndex": read_index}
            )
        present = {entry["id"] for entry in result["state"]}
        missing = sorted(sim.read_required.get(query_id, set()) - present)
        if missing:
            violations.append(
                {"type": "staleRead", "id": query_id, "missing": missing}
            )
    return violations

def _liveness_report(sim) -> dict:
    """Per-check outcomes in input order; every failed outcome is also
    listed as a violation."""
    checks = [sim.liveness_results[check["id"]] for check in sim.liveness_checks]
    violations = [check for check in checks if check["status"] == "failed"]
    return {"checks": checks, "violations": violations}

def build_report(sim) -> dict:
    leaders = {str(term): names for term, names in sorted(sim.leaders_by_term.items())}
    violations = [
        {"term": term, "leaders": list(names)}
        for term, names in sorted(sim.leaders_by_term.items())
        if len(names) > 1
    ]
    report = {
        "timeline": sim.timeline,
        "nodes": {
            name: _node_report(sim, name, st)
            for name, st in sim.state.items()
        },
        "clients": _clients_report(sim),
    }
    if sim.read_queries_provided:
        report["reads"] = _reads_report(sim)
    report["electionSafety"] = {
        "leadersByTerm": leaders,
        "violations": violations,
    }
    report["logMatching"] = {"violations": _log_matching_violations(sim)}
    report["stateMachineSafety"] = {"violations": _state_machine_safety_violations(sim)}
    if sim.read_queries_provided:
        report["linearizability"] = {
            "violations": _linearizability_violations(sim)
        }
    if sim.membership_enabled:
        report["membership"] = _membership_report(sim)
    if sim.liveness_provided:
        report["liveness"] = _liveness_report(sim)
    return report

"""Read-only replay verification of a saved ``simulate`` result.

``replay`` reruns the deterministic simulation on the original scenario and
compares the freshly computed result against the saved result field by field.
It never reads the wall clock, never uses randomness and never creates or
modifies files, so identical input produces byte-identical output.
"""

from __future__ import annotations

from .simulate import run_simulation


def _kind(value: object) -> str:
    """A JSON-level type tag. Booleans get their own tag so that ``true`` is
    never equal to the number 1, while ints and floats share ``number`` so
    that numbers compare by numeric value."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    return "object"


def _escape_token(token: str) -> str:
    """Escape one RFC 6901 reference token ('~' before '/')."""
    return token.replace("~", "~0").replace("/", "~1")


def _pointer(tokens: list[str]) -> str:
    if not tokens:
        return ""
    return "".join("/" + token for token in tokens)


def _first_difference(expected: object, actual: object, tokens: list[str]) -> str | None:
    """Return the RFC 6901 pointer of the first structural difference, or
    None when the two JSON values are equal.

    Arrays are compared by ascending index; objects recurse over the union of
    both sides' keys in ascending Unicode code-point order. A type or scalar
    difference ends the comparison at the current position; when an array
    prefix matches but the lengths differ, the pointer names the first
    missing index.
    """
    expected_kind = _kind(expected)
    actual_kind = _kind(actual)
    if expected_kind != actual_kind:
        return _pointer(tokens)

    if expected_kind in ("null", "bool", "number", "string"):
        if expected != actual:
            return _pointer(tokens)
        return None

    if expected_kind == "array":
        shared = min(len(expected), len(actual))
        for index in range(shared):
            found = _first_difference(expected[index], actual[index], tokens + [str(index)])
            if found is not None:
                return found
        if len(expected) != len(actual):
            return _pointer(tokens + [str(shared)])
        return None

    # Object: member order is irrelevant; visit the key union by Unicode code
    # point. A key present on only one side is itself the first difference.
    for key in sorted(set(expected) | set(actual)):
        token = _escape_token(key)
        if key not in expected or key not in actual:
            return _pointer(tokens + [token])
        found = _first_difference(expected[key], actual[key], tokens + [token])
        if found is not None:
            return found
    return None


def run_replay(scenario_raw: object, result_raw: object) -> dict:
    """Recompute the simulation for ``scenario_raw`` and compare it against
    the saved ``result_raw``.

    Returns ``{"status": "matched"}`` on equality, otherwise an object with
    ``status: "mismatched"``, the RFC 6901 pointer of the first difference,
    presence flags for both sides and the present value(s). Scenario
    validation errors propagate as :class:`ScenarioError` exactly as in
    ``simulate``.
    """
    expected = run_simulation(scenario_raw)

    path = _first_difference(expected, result_raw, [])
    if path is None:
        return {"status": "matched"}

    mismatch = {
        "status": "mismatched",
        "path": path,
        "expectedPresent": False,
        "actualPresent": False,
    }
    expected_value, actual_value = _value_at(expected, path), _value_at(result_raw, path)
    if expected_value is not _MISSING:
        mismatch["expectedPresent"] = True
        mismatch["expected"] = expected_value
    if actual_value is not _MISSING:
        mismatch["actualPresent"] = True
        mismatch["actual"] = actual_value
    return mismatch


class _Missing:
    """Sentinel for a pointer position absent on one side (distinct from a
    real JSON null, which is a present value)."""


_MISSING = _Missing()


def _value_at(root: object, path: str) -> object:
    """Resolve an RFC 6901 pointer produced by the comparison against one
    side. Returns the ``_MISSING`` sentinel when an object member or array
    index is absent."""
    if path == "":
        return root
    current = root
    for raw_token in path.split("/")[1:]:
        token = raw_token.replace("~1", "/").replace("~0", "~")
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                return _MISSING
        elif isinstance(current, list) and token.isascii() and token.isdigit():
            index = int(token)
            if 0 <= index < len(current):
                current = current[index]
            else:
                return _MISSING
        else:
            return _MISSING
    return current

"""Command line entry point for consensus-protocol-lab."""

from __future__ import annotations

import argparse
import json
import math
import sys

from . import __version__
from .explore import run_explore
from .replay import run_replay
from .scenario import ScenarioError
from .simulate import run_simulation


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"non-finite JSON number token: {value}")


def _reject_non_finite(value: object) -> None:
    """Reject every non-finite number anywhere in a decoded JSON tree.

    ``parse_constant`` refuses the bare NaN/Infinity/-Infinity literals, but a
    number whose exponent overflows float range (e.g. 1e1000) decodes to a
    non-finite float without ever being seen as a constant token; such values
    can hide at any depth (for example inside a client command), so the whole
    tree is checked after decoding. Object keys and the strings "NaN" /
    "Infinity" / "-Infinity" are ordinary strings and never rejected.
    """
    stack = [value]
    while stack:
        current = stack.pop()
        if isinstance(current, float):
            if not math.isfinite(current):
                raise ValueError(f"non-finite JSON number: {current!r}")
        elif isinstance(current, dict):
            stack.extend(current.values())
        elif isinstance(current, list):
            stack.extend(current)


def _load_strict_json(text: str) -> object:
    """Decode strict JSON: no NaN/Infinity/-Infinity tokens and no non-finite
    numbers anywhere in the tree."""
    raw = json.loads(text, parse_constant=_reject_json_constant)
    _reject_non_finite(raw)
    return raw


def _cmd_simulate(path: str) -> int:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read scenario file: {exc}", file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print(f"error: scenario file is not valid UTF-8: {path}", file=sys.stderr)
        return 2
    try:
        raw = _load_strict_json(text)
    except ValueError as exc:
        print(f"error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    try:
        result = run_simulation(raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _cmd_explore(path: str) -> int:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read plan file: {exc}", file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print(f"error: plan file is not valid UTF-8: {path}", file=sys.stderr)
        return 2
    try:
        raw = _load_strict_json(text)
    except ValueError as exc:
        print(f"error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    try:
        result = run_explore(raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _read_utf8_json(path: str, kind: str) -> tuple[bool, object]:
    """Read and decode a UTF-8 JSON file for replay. Returns (ok, value);
    on failure prints one ``error:`` line to stderr and returns (False,
    None). ``kind`` labels the file in the messages."""
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read {kind} file: {exc}", file=sys.stderr)
        return False, None
    except UnicodeDecodeError:
        print(f"error: {kind} file is not valid UTF-8: {path}", file=sys.stderr)
        return False, None
    try:
        # Strict JSON boundary: refuse the non-standard NaN/Infinity tokens
        # and any non-finite number an exponent overflow could decode to,
        # anywhere in the tree.
        return True, _load_strict_json(text)
    except ValueError as exc:
        print(f"error: invalid JSON in {kind} file: {exc}", file=sys.stderr)
        return False, None


def _cmd_replay(scenario_path: str, result_path: str) -> int:
    ok, scenario_raw = _read_utf8_json(scenario_path, "scenario")
    if not ok:
        return 2
    ok, result_raw = _read_utf8_json(result_path, "result")
    if not ok:
        return 2
    # A non-object RESULT cannot carry the comparison contract (status is
    # reported as mismatched only when the top level is an object).
    if not isinstance(result_raw, dict):
        print("error: result file must contain a JSON object", file=sys.stderr)
        return 2
    try:
        report = run_replay(scenario_raw, result_raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    # Compact, member order fixed by construction: byte-identical for
    # identical input.
    print(json.dumps(report, ensure_ascii=False, separators=(",", ":")))
    return 0 if report["status"] == "matched" else 1


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="consensus-protocol-lab", description="Deterministic simulation lab for Raft-style consensus protocols")
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")
    simulate = sub.add_parser("simulate", help="run a deterministic Raft leader-election simulation")
    simulate.add_argument("scenario", help="path to a UTF-8 JSON scenario file")
    explore = sub.add_parser("explore", help="enumerate bounded message-fault combinations over a base scenario")
    explore.add_argument("plan", help="path to a UTF-8 JSON plan file")
    replay = sub.add_parser("replay", help="recompute a simulation and field-compare it against a saved result")
    replay.add_argument("scenario", help="path to the UTF-8 JSON scenario file")
    replay.add_argument("result", help="path to a UTF-8 JSON file holding a simulate result")
    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0
    if args.command == "simulate":
        return _cmd_simulate(args.scenario)
    if args.command == "explore":
        return _cmd_explore(args.plan)
    if args.command == "replay":
        return _cmd_replay(args.scenario, args.result)

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Bounded enumeration of message-fault combinations over a base scenario.

``explore`` reuses the deterministic simulator for every combination: it
never reads the wall clock, never uses randomness and never creates files,
so identical PLAN input produces byte-identical output.
"""

from __future__ import annotations

from itertools import combinations

from .scenario import ScenarioError, _require_int, parse_scenario
from .simulate import _Simulator

_PLAN_FIELDS = {
    "scenario",
    "candidates",
    "maxFaults",
    "maxCases",
    "minimizeFailures",
    "eventCandidates",
    "maxEventFaults",
}
_REQUIRED_PLAN_FIELDS = {"scenario", "candidates", "maxFaults", "maxCases"}
_EVENT_CANDIDATE_FIELDS = {"network", "node"}

# Reports whose violation lists decide a case's status. A report the scenario
# does not enable is absent from the result and plays no part in the verdict.
_CHECKED_REPORTS = (
    "electionSafety",
    "logMatching",
    "stateMachineSafety",
    "linearizability",
    "liveness",
)


def _failure_signature(result: dict) -> tuple[str, ...]:
    """Names of the enabled reports whose violation list is non-empty, in
    fixed check-priority order. Two cases share a failure signature exactly
    when they violate the same set of invariants."""
    return tuple(
        key
        for key in _CHECKED_REPORTS
        if key in result and result[key]["violations"]
    )


def _merged_config(
    scenario_raw: dict,
    candidates: list,
    event_candidates: list,
    event_selected: tuple[int, ...],
) -> dict:
    """Validate and normalize the scenario for one event combination: the
    base scenario with every message-fault candidate presented as its
    messageFaults and the selected events appended to the corresponding
    collections. Base entries keep their positions, so at one timestamp
    same-kind base events are processed before the selected candidates (in
    candidate-index order), and network events still precede node events."""
    merged = dict(scenario_raw)
    merged["messageFaults"] = candidates
    network = [
        event_candidates[i]["network"] for i in event_selected if "network" in event_candidates[i]
    ]
    node = [event_candidates[i]["node"] for i in event_selected if "node" in event_candidates[i]]
    if network or "faults" in merged:
        merged["faults"] = list(merged.get("faults", [])) + network
    if node or "nodeEvents" in merged:
        merged["nodeEvents"] = list(merged.get("nodeEvents", [])) + node
    return parse_scenario(merged)


def run_explore(raw: object) -> dict:
    """Validate a decoded JSON PLAN and run every fault combination."""
    if not isinstance(raw, dict):
        raise ScenarioError("plan must be a JSON object")
    unknown = sorted(set(raw) - _PLAN_FIELDS)
    if unknown:
        raise ScenarioError(f"unknown field(s): {', '.join(unknown)}")
    missing = sorted(_REQUIRED_PLAN_FIELDS - set(raw))
    if missing:
        raise ScenarioError(f"missing field(s): {', '.join(missing)}")

    has_event_candidates = "eventCandidates" in raw
    has_max_event_faults = "maxEventFaults" in raw
    if has_event_candidates != has_max_event_faults:
        raise ScenarioError(
            "eventCandidates and maxEventFaults must be provided together"
        )
    events_enabled = has_event_candidates

    minimize_failures = raw.get("minimizeFailures", False)
    if not isinstance(minimize_failures, bool):
        raise ScenarioError("minimizeFailures must be a boolean")

    scenario_raw = raw["scenario"]
    if not isinstance(scenario_raw, dict):
        raise ScenarioError("scenario must be a JSON object")
    if "messageFaults" in scenario_raw:
        raise ScenarioError("scenario must not contain messageFaults")

    candidates = raw["candidates"]
    if not isinstance(candidates, list):
        raise ScenarioError("candidates must be a list")
    if not candidates:
        raise ScenarioError("candidates must not be empty")

    max_faults = _require_int(raw["maxFaults"], "maxFaults", 0)
    if max_faults > len(candidates):
        raise ScenarioError("maxFaults must not exceed the number of candidates")
    max_cases = _require_int(raw["maxCases"], "maxCases", 1)

    event_candidates: list = []
    max_event_faults = 0
    if events_enabled:
        event_candidates = raw["eventCandidates"]
        if not isinstance(event_candidates, list):
            raise ScenarioError("eventCandidates must be a list")
        if not event_candidates:
            raise ScenarioError("eventCandidates must not be empty")
        for index, item in enumerate(event_candidates):
            label = f"eventCandidates[{index}]"
            if not isinstance(item, dict):
                raise ScenarioError(f"{label} must be an object")
            unknown = sorted(set(item) - _EVENT_CANDIDATE_FIELDS)
            if unknown:
                raise ScenarioError(
                    f"{label} has unknown field(s): {', '.join(unknown)}"
                )
            if len(set(item) & _EVENT_CANDIDATE_FIELDS) != 1:
                raise ScenarioError(
                    f"{label} must declare exactly one of network or node"
                )
        max_event_faults = _require_int(raw["maxEventFaults"], "maxEventFaults", 0)
        if max_event_faults > len(event_candidates):
            raise ScenarioError(
                "maxEventFaults must not exceed the number of event candidates"
            )

    # Validate the base scenario and every candidate rule with the original
    # scenario validation by presenting the candidates as its messageFaults;
    # this also rejects duplicated full selectors. Each normalized rule keeps
    # its candidate index in its "index" field.
    combined = dict(scenario_raw)
    combined["messageFaults"] = candidates
    config = parse_scenario(combined)
    rules = config["messageFaults"]

    # The empty combination comes first, then combinations of ascending size;
    # itertools.combinations yields index tuples in numeric lexicographic
    # order, and each tuple is ascending, so selected rules and events are
    # always injected in original candidate-index order.
    message_combos = [
        combo
        for size in range(max_faults + 1)
        for combo in combinations(range(len(candidates)), size)
    ]
    event_combos = [
        combo
        for size in range(max_event_faults + 1)
        for combo in combinations(range(len(event_candidates)), size)
    ]

    total = len(message_combos) * len(event_combos)
    if total > max_cases:
        raise ScenarioError(
            f"combination count {total} exceeds maxCases {max_cases}"
        )

    if events_enabled:
        # Every merged scenario is validated before any simulation runs:
        # first each event candidate on its own (in the base context, exactly
        # like the message-fault candidates above), then every enumerated
        # combination, whose appended events may jointly violate a constraint
        # such as crash/restart alternation.
        for index in range(len(event_candidates)):
            _merged_config(scenario_raw, candidates, event_candidates, (index,))
        event_configs = [
            _merged_config(scenario_raw, candidates, event_candidates, combo)
            for combo in event_combos
        ]
    else:
        event_configs = [config]

    # Message-fault combinations form the outer loop in their established
    # order; within each, the empty event combination comes first, then
    # event combinations of ascending size in numeric lexicographic order.
    cases = []
    # Only populated while minimizing: signature -> list of
    # (selected index tuple, selected event index tuple, caseId).
    # Minimization never runs extra simulations; it only references cases
    # enumerated here, so those references do not count against maxCases.
    by_signature: dict[
        tuple[str, ...], list[tuple[tuple[int, ...], tuple[int, ...], int]]
    ] = {}
    passed = 0
    case_id = 0
    for selected in message_combos:
        for event_index, event_selected in enumerate(event_combos):
            case_config = dict(event_configs[event_index])
            case_config["messageFaults"] = [rules[i] for i in selected]
            result = _Simulator(case_config).run()
            signature = _failure_signature(result)
            if signature:
                status = "failed"
            else:
                status = "passed"
                passed += 1
            case = {"caseId": case_id, "selected": list(selected)}
            if events_enabled:
                case["selectedEvents"] = list(event_selected)
            case["status"] = status
            case["result"] = result
            if minimize_failures and signature:
                by_signature.setdefault(signature, []).append(
                    (selected, event_selected, case_id)
                )
            cases.append(case)
            case_id += 1

    if minimize_failures:
        for case in cases:
            if case["status"] != "failed":
                continue
            signature = _failure_signature(case["result"])
            selected = tuple(case["selected"])
            selected_events = tuple(case.get("selectedEvents", ()))
            # Every minimizing combination must be reachable by deleting
            # candidates of both kinds from this case (sub-combinations of
            # its selected indices) and reproduce its exact failure
            # signature: a combination that passes or that only shows other
            # violations is never selected. The fewest total candidates win;
            # ties are broken by the numeric lexicographic order of the
            # selected index array, then of the selectedEvents array. The
            # case itself always qualifies.
            minimal_selected, minimal_events, minimal_case_id = min(
                (
                    entry
                    for entry in by_signature[signature]
                    if set(entry[0]).issubset(selected)
                    and set(entry[1]).issubset(selected_events)
                ),
                key=lambda entry: (len(entry[0]) + len(entry[1]), entry[0], entry[1]),
            )
            case["failureReports"] = list(signature)
            case["minimalSelected"] = list(minimal_selected)
            if events_enabled:
                case["minimalSelectedEvents"] = list(minimal_events)
            case["minimalCaseId"] = minimal_case_id

    return {
        "totalCases": len(cases),
        "passedCases": passed,
        "failedCases": len(cases) - passed,
        "cases": cases,
    }

"""Liveness evaluation.

``_Liveness`` owns the liveness checks: at every fully drained timestamp
inside a check's window it evaluates whether the target condition holds
(leader online, command committed, read completed, membership change
committed) and, at the deadline, why it failed. It only reads the shared
bookkeeping the other domains have already written — it never mutates node
state, sends messages or schedules events.

Provides:
    _evaluate_liveness — run every open check whose window contains the
        drained timestamp (simulator loop)

Requires (from the composing simulator):
    ``state``, ``liveness_checks``, ``liveness_results``,
    ``committed_command_ids``, ``accepted_command_ids``, ``rejected``,
    ``read_results``, ``change_results``, ``stable_commit_times`` and the
    ``leader_online`` flag it maintains; plus kernel._record.
"""

from __future__ import annotations

from ..node import ROLE_LEADER


class _Liveness:
    # -- liveness checks -------------------------------------------------------

    def _has_online_leader(self) -> bool:
        return any(
            st.online and st.role == ROLE_LEADER for st in self.state.values()
        )

    def _command_present_anywhere(self, command_id: str) -> bool:
        """Whether an accepted command still survives in some node's applied
        history or uncompacted log suffix."""
        for st in self.state.values():
            if any(entry.get("id") == command_id for entry in st.applied):
                return True
            if any(entry.get("id") == command_id for entry in st.log):
                return True
        return False

    def _liveness_satisfied(self, check: dict) -> bool:
        check_type = check["type"]
        target = check["target"]
        if check_type == "leaderElected":
            return self.leader_online
        if check_type == "clientCommitted":
            return target in self.committed_command_ids
        if check_type == "readCompleted":
            result = self.read_results.get(target)
            return result is not None and result.get("outcome") == "completed"
        # membershipCommitted: the stable configuration entry has been applied
        # (the change committed).
        return target in self.stable_commit_times

    def _liveness_failure_reason(self, check: dict) -> str | None:
        """A terminal reason once the target can never satisfy the check;
        None while satisfaction is still possible."""
        check_type = check["type"]
        target = check["target"]
        if check_type == "clientCommitted":
            if target in self.rejected:
                return "targetRejected"
            if (
                target in self.accepted_command_ids
                and target not in self.committed_command_ids
                and not self._command_present_anywhere(target)
            ):
                # Accepted earlier, but its uncommitted entry was truncated by
                # a higher-term leader: it can never commit anymore.
                return "targetSuperseded"
            return None
        if check_type == "readCompleted":
            result = self.read_results.get(target)
            if result is not None and result.get("outcome") == "rejected":
                return "targetRejected"
            return None
        if check_type == "membershipCommitted":
            result = self.change_results.get(target)
            if result is not None and result.get("outcome") == "rejected":
                return "targetRejected"
            return None
        return None

    def _evaluate_liveness(self, time: int) -> None:
        """Run every open check whose window contains this timestamp, in
        input order, against the fully drained state at ``time``."""
        self.leader_online = self._has_online_leader()
        for check in self.liveness_checks:
            check_id = check["id"]
            if check_id in self.liveness_results:
                continue
            if time < check["startTime"] or time > check["deadline"]:
                continue
            result = {"id": check_id, "checkType": check["type"]}
            if check["target"] is not None:
                result["target"] = check["target"]
            if not self._liveness_satisfied(check):
                if time < check["deadline"]:
                    # The first satisfying moment may still arrive later in
                    # the window; a terminal target failure likewise surfaces
                    # as the reason at the deadline.
                    continue
                result["status"] = "failed"
                result["time"] = time
                result["reason"] = self._liveness_failure_reason(check) or "deadlineExceeded"
            else:
                result["status"] = "satisfied"
                result["time"] = time
            self.liveness_results[check_id] = result
            entry = {"type": "livenessResult", "id": check_id, "checkType": result["checkType"]}
            if check["target"] is not None:
                entry["target"] = check["target"]
            entry["status"] = result["status"]
            if result["status"] == "failed":
                entry["reason"] = result["reason"]
            self._record(entry)

"""Configuration views and quorum arithmetic shared by every domain.

``_ConfigView`` is the single place that knows how a (stable or joint)
configuration is shaped and what "majority" means under it: which nodes are
voters, whether a node may vote or campaign, and whether a vote set or a
replication position satisfies every quorum group. Elections, replication,
membership, reads and the report layer all consult these primitives instead
of re-deriving them, so a configuration change takes effect everywhere
through one code path.

Provides:
    _config_groups, _config_quorums, _is_voter, _can_vote, _store_config,
    _joint_config, _stable_config, _has_vote_majorities,
    _replicated_by_majorities

Requires (from the composing simulator):
    ``state`` (per-node ``_Node``) and ``initial_config``.
"""

from __future__ import annotations

from ..node import CONFIG_JOINT, CONFIG_STABLE


class _ConfigView:
    # -- configuration -------------------------------------------------------

    @staticmethod
    def _config_groups(config: dict) -> tuple[frozenset[str], frozenset[str]]:
        """The (old, new) voter sets of a configuration. Stable configurations
        carry the same set twice; joint configurations carry both."""
        return frozenset(config["old"]), frozenset(config["new"])

    def _config_quorums(self, config: dict) -> list[frozenset[str]]:
        old, new = self._config_groups(config)
        if config.get("type") == CONFIG_JOINT:
            return [old, new]
        return [new]

    def _is_voter(self, name: str, config: dict) -> bool:
        old, new = self._config_groups(config)
        return name in old or name in new

    def _can_vote(self, name: str) -> bool:
        """Current voting/election eligibility from the node's newest
        configuration: learners and nodes not present in the latest config
        neither vote nor campaign. A removed node that learns a configuration
        adding it back regains eligibility."""
        st = self.state[name]
        return self._is_voter(name, st.latest_config(self.initial_config))

    @staticmethod
    def _store_config(config: dict) -> dict:
        old, new = _ConfigView._config_groups(config)
        return {
            "type": config.get("type", CONFIG_STABLE),
            "old": sorted(old),
            "new": sorted(new),
        }

    def _joint_config(self, voters: frozenset[str], action: str, member: str) -> dict:
        if action == "add":
            new_voters = voters | {member}
        else:
            new_voters = voters - {member}
        return {"type": CONFIG_JOINT, "old": sorted(voters), "new": sorted(new_voters)}

    @staticmethod
    def _stable_config(voters: frozenset[str]) -> dict:
        ordered = sorted(voters)
        return {"type": CONFIG_STABLE, "old": ordered, "new": ordered}

    def _has_vote_majorities(self, candidate: str, votes: set[str], config: dict) -> bool:
        for group in self._config_quorums(config):
            needed = len(group) // 2 + 1
            if len([v for v in votes if v in group]) < needed:
                return False
        return True

    def _replicated_by_majorities(self, leader: str, index: int, config: dict) -> bool:
        """Whether ``index`` is present on a strict majority of every quorum
        group (the leader itself counts in any group it belongs to)."""
        st = self.state[leader]
        for group in self._config_quorums(config):
            needed = len(group) // 2 + 1
            points = []
            for peer in group:
                if peer == leader:
                    points.append(st.last_log_index())
                else:
                    points.append(st.match_index.get(peer, 0))
            if len([point for point in points if point >= index]) < needed:
                return False
        return True
